def arrow():return '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>'
def button(text,href,kind='primary',extra=''):
 return f'<a class="button button--{kind}" href="{e(href)}" {extra}><span>{text}</span>{arrow()}</a>'
def image(name,alt,cls='',lazy=True,sizes=None,extra=''):
 meta=images[name]
 variants=meta['variants']
 fallback=next((v for v in variants if v['width']==960),variants[-1])
 if sizes is None:
  sizes='(max-width: 640px) calc(100vw - 40px), (max-width: 1180px) 46vw, 600px'
  if cls=='hero-food':sizes='(max-width: 640px) 100vw, 53vw'
  elif cls=='portrait-detail':sizes='(max-width: 640px) 38vw, 240px'
 srcset=', '.join('@/img/optimized/'+v['file']+' '+str(v['width'])+'w' for v in variants)
 return f'<img class="{cls}" src="@/img/optimized/{fallback["file"]}" srcset="{srcset}" sizes="{sizes}" alt="{e(alt)}" width="{meta["width"]}" height="{meta["height"]}" data-full="@/img/optimized/{name}.webp" '+('loading="lazy" decoding="async"' if lazy else 'fetchpriority="high" decoding="async"')+f' {extra}>'
def structured_data(title,description,route,active):
 restaurant={'@type':'Restaurant','@id':BASE+'/#restaurant','name':'Ersan’s Kebap','url':BASE+'/','image':BASE+'/img/optimized/laden-1.webp','logo':BASE+'/img/optimized/logo-header.webp','telephone':'+49 151 59078248','email':'Yavuzersan24@gmail.com','address':{'@type':'PostalAddress','streetAddress':'Dr.-Martin-Luther-Straße 18','postalCode':'91550','addressLocality':'Dinkelsbühl','addressCountry':'DE'},'servesCuisine':['Türkisch','Döner','Pizza'],'hasMenu':BASE+'/html/menu.html','hasMap':MAP,'openingHoursSpecification':[{'@type':'OpeningHoursSpecification','dayOfWeek':['Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],'opens':start,'closes':end} for start,end in [('12:00','14:00'),('17:00','21:00')]]}
 webpage={'@type':{'contact':'ContactPage','story':'AboutPage'}.get(active,'WebPage'),'@id':BASE+route+'#webpage','url':BASE+route,'name':title+' · Ersan’s Kebap','description':description,'inLanguage':'de-DE','about':{'@id':BASE+'/#restaurant'},'isPartOf':{'@id':BASE+'/#website'}}
 graph=[restaurant,{'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':'Ersan’s Kebap','inLanguage':'de-DE'},webpage]
 if route!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Startseite','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title,'item':BASE+route}]})
 if active=='menu':graph.append({'@type':'Menu','@id':BASE+'/html/menu.html#speisekarte','name':'Speisekarte von Ersan’s Kebap','url':BASE+route,'inLanguage':'de-DE','hasMenuSection':[{'@type':'MenuSection','name':g['name'],'hasMenuItem':[{'@type':'MenuItem','name':i['name'],'offers':{'@type':'Offer','price':i['price'].replace(' €','').replace(',','.'),'priceCurrency':'EUR'}} for i in g['items']]} for g in menu]})
 return json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False,separators=(',',':')).replace('<',chr(92)+'u003c')
def brand():return '<span class="wordmark">ersan’s<span class="brand-dot">.</span></span><span class="brand-sub">KEBAP · DINKELSBÜHL</span>'
