def page(title,desc,body,active='',home=False):
 route='/' if home else '/html/'+({'menu':'menu','story':'ueber-uns','contact':'kontakt'}.get(active,'impressum' if title=='Impressum' else 'datenschutz'))+'.html'
 preview='pizza' if active=='menu' else 'laden-1' if active in ['contact','story'] else 'hero-kebap'
 extra_css=f'<link rel="stylesheet" href="@/css/menu.css?v={VERSION}">' if active=='menu' else ''
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#1a2923"><title>{title} · Ersan’s Kebap</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{BASE}{route}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:locale" content="de_DE"><meta property="og:site_name" content="Ersan’s Kebap"><meta property="og:url" content="{BASE}{route}"><meta property="og:title" content="{e(title)} · Ersan’s Kebap"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}/img/optimized/{preview}.webp"><meta property="og:image:alt" content="{e('Pizza aus dem Ofen bei Ersan’s Kebap' if active=='menu' else 'Ersan’s Kebap in Dinkelsbühl')}"><meta name="twitter:card" content="summary_large_image"><meta name="color-scheme" content="light"><link rel="icon" href="@/img/favicon.svg" type="image/svg+xml"><link rel="preload" href="@/fonts/dm-sans-400.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="@/fonts/instrument-serif-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="@/css/styles.css?v={VERSION}">{extra_css}<script type="application/ld+json">{structured_data(title,desc,route,active)}</script><script src="@/js/app.js?v={VERSION}" defer></script></head><body id="top" class="{active} {'is-home' if home else ''}">{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
def write(file,text):
 p=ROOT/file;p.parent.mkdir(parents=True,exist_ok=True);prefix='../'*(len(Path(file).parts)-1) or './';text=text.replace('@/',prefix)
 text=re.sub(r'(?=</?(?:section|header|footer|main|nav|article|aside|div|form|ul|li|dl|dt|dd|label|h1|h2|h3|p|script|meta|link|body|head|html|input|textarea|details|summary)\b)', '\n', text)
 text='\n'.join(line.rstrip() for line in text.splitlines())
 text=re.sub(r'\n{3,}', '\n\n', text)
 p.write_text(text.strip()+'\n')
