filterNames=[('alle','Alles entdecken'),('doener','Döner & Dürüm'),('pizza','Pizza & Ofen'),('klassiker','Currywurst & mehr'),('vegetarisch','Pide & Beilagen'),('salate','Salate & Snacks'),('spezial','Spezial & Angebote'),('getraenke','Getränke')]
groupIntro={'salate':'Frisch anfangen. Oder einfach leicht bleiben.','spezial':'Für alle, die etwas Besonderes suchen.','doener':'Mit Salat, Soße und deinem guten Geschmack.','dueruem':'Gerollt oder als Lahmacun – frisch für dich.','klassiker':'Unsere Klassiker auf dem Teller und im Brot.','vegetarisch':'Pide, Fladenbrot und passende Beilagen.','pizza':'Frisch aus dem Ofen. Mit deinem Lieblingsbelag.','flammkuchen':'Knusprig dünn und herzhaft belegt.','calzone':'Gut gefüllt. Heiß aus dem Ofen.','getraenke':'Etwas Kühles dazu?','angebote':'Gut zusammen. Gemeinsam genießen.'}
def menu_row(item):
 name=item['name'];title=name;description=''
 for separator in [' – ',' mit ']:
  if separator in name:
   title,tail=name.split(separator,1);description=('mit ' if separator==' mit ' else '')+tail;break
 codes=('<sup title="Kennzeichnungen aus der Speisekarte">'+e(item['additives'])+'</sup>') if item['additives'] else ''
 return f'<li class="menu-item" data-menu-item data-search="{e(name)}"><span class="menu-item-name"><strong>{e(title)}{codes}</strong>'+('<span class="menu-item-description">'+e(description)+'</span>' if description else '')+f'</span><span class="menu-item-price">{e(item["price"])}</span></li>'
menu_photos={'doener':('hero-kebap','Dönerbrot als illustrativer Serviervorschlag'),'pizza':('pizza','Pizza frisch aus dem Ofen'),'klassiker':('currywurst','Currywurst mit Pommes bei Ersan’s')}
groups=''
for k,g in enumerate(menu):
 rows=''.join(menu_row(i) for i in g['items'])
 notes=''.join('<p class="menu-group-note">'+e(n)+'</p>' for n in g['notes'])
 photo=''
 if g['id'] in menu_photos:
  name,alt=menu_photos[g['id']];photo='<figure class="menu-chapter-photo">'+image(name,alt,sizes='(max-width: 640px) 160px, 220px')+'</figure>'
 groups+=f'''<section class="menu-group" id="{g['id']}" data-menu-group="{g['filter']}" aria-labelledby="heading-{g['id']}"><div class="menu-group-heading"><span class="menu-group-index">{k+1:02} /</span><h2 id="heading-{g['id']}">{e(g['name'])}</h2><p>{groupIntro[g['id']]}</p>{photo}</div><div class="menu-group-body"><ul class="menu-items">{rows}</ul>{notes}</div></section>'''
