menuBody=f'''<section class="menu-cover shell"><div class="menu-cover-copy"><p class="eyebrow">ERSAN’S KEBAP · DINKELSBÜHL</p><h1>Guter Hunger.<br><em>Gute Auswahl.</em></h1><p class="menu-cover-intro">Döner auf die Hand. Pizza aus dem Ofen. Oder doch dein Lieblingsgericht auf dem Teller?</p><a class="button button--primary" href="#speisekarte"><span>Entdecke die Speisekarte</span>{arrow()}</a><span class="menu-cover-footnote">Frisch zubereitet. Bei uns genießen oder mitnehmen.</span></div><figure class="menu-cover-photo">{image('pizza','Pizza mit frischen Zutaten bei Ersan’s Kebap','',False,sizes='(max-width: 640px) calc(100vw - 40px), 48vw')}<figcaption><span>HEISS AUS DEM OFEN</span><strong>Ein guter Plan<br>für deinen Hunger.</strong></figcaption></figure></section><div class="menu-shortcuts shell">{quicklinks}</div><section class="menu-section shell" id="speisekarte" aria-label="Gerichte und Preise"><div class="menu-toolbar"><div class="menu-toolbar-top"><div><p class="eyebrow">FÜR DEN KLEINEN & GROSSEN HUNGER</p><h2>Was darf’s sein?</h2></div><div class="menu-search-bar"><label class="menu-search"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg><input type="search" id="menu-search" placeholder="Gericht suchen …" aria-label="Speisekarte durchsuchen" aria-controls="menu-content"></label></div></div><div class="menu-filters" role="group" aria-label="Speisekarte nach Kategorie filtern">{filters}</div></div><div class="menu-results-heading"><span id="menu-result-count" role="status">64 Gerichte & Getränke</span><span>Alle Preise in Euro</span></div><div class="menu-content" id="menu-content">{groups}<div class="menu-empty" hidden><span class="eyebrow">NOCH NICHT FÜNDIG?</span><h2>Dein Hunger ist<br><em>bestimmt dabei.</em></h2><p>Versuch einen anderen Suchbegriff oder entdecke wieder die ganze Karte.</p><button type="button" class="button button--primary" data-reset-menu>Alles anzeigen {arrow()}</button></div><div class="menu-additives"><details><summary>Zusatzstoffe & Kennzeichnungen</summary><p>1 Farbstoffe · 2 Konservierungsstoffe · 3 Antioxidationsmittel · 4 Geschmacksverstärker · 5 Phosphat · 6 geschwärzt · 8 Nitritpökelsalz · 12 koffeinhaltig · 13 taurinhaltig · 14 Gluten · 15 Sulfite · 16 Gerstenmehl · 17 Weizenmehl</p><p>Die Kennzeichnungen stammen aus unserer bisherigen Speisekarte. Bitte frage bei Unverträglichkeiten vor der Bestellung persönlich nach.</p></details><a href="{PHONE}">Fragen zu Zutaten? Ruf uns an ↗</a></div></div></section><section class="menu-order"><div class="shell"><div><p class="eyebrow">HUNGER GEKLÄRT?</p><h2>Wir machen’s<br><em>frisch für dich.</em></h2></div><div><p>Für heute am besten anrufen. Vorbestellungen per Formular bitte <strong>mindestens 1 Tag vorher</strong> anfragen und unsere Bestätigung abwarten.</p><div class="menu-order-actions">{button('0151 590 78 248',PHONE,'light')}<a class="under-link" href="@/html/kontakt.html#vorbestellen">Vorbestellung anfragen ↗</a></div></div></div></section>'''
write('html/menu.html',page('Speisekarte & Preise in Dinkelsbühl','Die vollständige Speisekarte von Ersan’s Kebap: Döner, Dürüm, Pizza, Falafel, Pide, Currywurst, Salate und Getränke mit Preisen.',menuBody,'menu'))
story=f'''<section class="story-hero shell"><div><p class="eyebrow">DAS SIND WIR.</p><h1>Unser Laden.<br>Unsere Geschichte.<br><em>Dein Ersan’s.</em></h1><p>Ein familiärer Imbiss in Dinkelsbühl.<br>Mit viel Arbeit aufgebaut. Mit Herz weitergemacht.</p><a class="under-link" href="#geschichte">Unsere Geschichte entdecken ↓</a></div><div class="story-hero-photo">{image('neuer-laden2','Ersan bei der Zubereitung in seinem Laden','',False)}<span class="image-caption">ECHTE MENSCHEN. ECHTES HANDWERK.</span></div></section><section class="story-statement shell section" data-reveal><span class="eyebrow">WARUM WIR DAS MACHEN.</span><p>Weil gutes Essen Menschen zusammenbringt.<br>Und weil ein kleiner Laden <em>viel Herz haben kann.</em></p></section><section class="journey shell" id="geschichte"><article class="journey-chapter" data-reveal><div class="chapter-photos"><button type="button" data-gallery="renovierung" data-gallery-index="0" aria-label="Renovierung vergrößert ansehen">{image('laden-vorher1','Der neue Standort während der Renovierung')}</button><button type="button" data-gallery="renovierung" data-gallery-index="1" aria-label="Zweites Renovierungsfoto vergrößern">{image('laden-vorher2','Der renovierte Gastraum')}</button></div><div class="chapter-copy"><span class="chapter-number">01 / DER ANFANG</span><h2>Eine Idee.<br><em>Ein neuer Ort.</em></h2><p>Ein neuer Standort und jede Menge Arbeit: Wir haben renoviert und eingerichtet, um einen Ort zu schaffen, an dem frisches Essen und eine familiäre Atmosphäre zusammenkommen.</p></div></article><article class="journey-chapter reversed" data-reveal><div class="chapter-photos"><button type="button" data-gallery="wasserschaden" data-gallery-index="0" aria-label="Foto vom Wasserschaden ansehen">{image('wasserschaden1','Der Wasserschaden im frisch renovierten Laden')}</button><button type="button" data-gallery="wasserschaden" data-gallery-index="1" aria-label="Weiteres Foto vom Wasserschaden ansehen">{image('wasserschaden2','Die Folgen des Wasserschadens')}</button></div><div class="chapter-copy"><span class="chapter-number">02 / DER RÜCKSCHLAG</span><h2>Kurz zurück.<br><em>Dann weiter.</em></h2><p>Gerade war alles fertig, da kam ein Wasserschaden. Nach der vielen Arbeit war das ein harter Rückschlag. Trotzdem stand für uns fest: Wir machen weiter.</p></div></article><article class="journey-chapter" data-reveal><div class="chapter-photos"><button type="button" data-gallery="neustart" data-gallery-index="0" aria-label="Ersan am Ofen vergrößert ansehen">{image('neuer-laden1','Ersan am Ofen nach dem Neustart')}</button><button type="button" data-gallery="neustart" data-gallery-index="1" aria-label="Ersan im Laden vergrößert ansehen">{image('neuer-laden2','Ersan bereitet ein Gericht zu')}</button></div><div class="chapter-copy"><span class="chapter-number">03 / DER NEUSTART</span><h2>Wieder da.<br><em>Für dich.</em></h2><p>Heute stehen wir wieder für euch im Laden, bereiten zu und freuen uns über bekannte und neue Gesichter. Danke an alle, die uns auf diesem Weg unterstützt haben.</p>{button('Die Speisekarte entdecken','@/html/menu.html','outline')}</div></article></section>{visit()}'''
write('html/ueber-uns.html',page('Unser Laden in Dinkelsbühl','Lerne Ersan’s Kebap in Dinkelsbühl kennen: unser familiärer Laden, die Renovierung, der Rückschlag und unser Neustart.',story,'story'))
contact=f'''<section class="page-intro shell"><div><p class="eyebrow">KONTAKT & VORBESTELLUNG.</p><h1>Guter Hunger?<br><em>Wir sind da.</em></h1></div><div class="intro-aside"><p>Für spontane Bestellungen am besten anrufen.<br>Für geplante Abholungen nutze unser Formular.</p><a class="contact-phone" href="{PHONE}">0151 590 78 248 ↗</a></div></section><section class="contact-section shell" id="vorbestellen"><aside class="contact-details"><p class="eyebrow">KURZ ANRUFEN. PERSÖNLICH KLÄREN.</p><h2>Dein Weg<br><em>zu uns.</em></h2><dl><div><dt>Telefon</dt><dd><a href="{PHONE}">0151 590 78 248</a></dd></div><div><dt>E-Mail</dt><dd><a href="mailto:Yavuzersan24@gmail.com">Yavuzersan24@gmail.com</a></dd></div><div><dt>Adresse</dt><dd>Dr.-Martin-Luther-Straße 18<br>91550 Dinkelsbühl</dd></div><div><dt>Geöffnet</dt><dd>Di–So: 12–14 & 17–21 Uhr<br>Montag Ruhetag</dd></div></dl><a class="under-link" href="{MAP}" target="_blank" rel="noopener">Route planen ↗</a><div class="contact-note"><span>GUT ZU WISSEN</span><p>Vorbestellungen über das Formular bitte mindestens <strong>einen Tag vorher</strong> anfragen und auf unsere Bestätigung warten. Kartenzahlung ist möglich.</p></div></aside><section class="preorder-panel" aria-labelledby="form-heading"><p class="eyebrow">MIT ETWAS VORLAUF.</p><h2 id="form-heading">Dein Essen.<br><em>Deine Wunschzeit.</em></h2><p class="form-intro">Sag uns, was du möchtest und wann du es abholen willst. Wir melden uns zur Bestätigung.</p><aside class="preorder-notice" id="preorder-notice" aria-labelledby="preorder-notice-heading"><h3 id="preorder-notice-heading">Wichtig für deine Vorbestellung</h3><p><strong>Mindestens 1 Tag vorher bestellen.</strong> Bitte plane deine Abholung mit diesem Vorlauf.</p><p><strong>Unsere persönliche Bestätigung abwarten.</strong> Erst nach unserer Bestätigung ist deine Bestellung angenommen.</p><a class="under-link" href="{PHONE}">Für heute? Bitte direkt anrufen ↗</a></aside><form id="preorderForm" aria-describedby="preorder-notice" action="https://formspree.io/f/mbdknvvg" method="POST"><input type="hidden" name="page" value="kontakt-vorbestellung"><div class="honeypot" aria-hidden="true"><label>Dieses Feld bitte frei lassen<input type="text" name="_gotcha" tabindex="-1" autocomplete="off"></label></div><div class="form-grid"><label>Vor- und Nachname <span>*</span><input required name="name" type="text" autocomplete="name" maxlength="120" placeholder="Wie heißt du?"></label><label>E-Mail-Adresse <span>*</span><input required name="email" type="email" autocomplete="email" maxlength="200" placeholder="name@beispiel.de"></label><label>Telefonnummer<input name="phone" type="tel" autocomplete="tel" maxlength="50" placeholder="Für Rückfragen, optional"></label><label>Gewünschte Abholzeit <span>*</span><input required name="time" type="text" maxlength="150" aria-describedby="preorder-notice" placeholder="z. B. Freitag, 18:30 Uhr"></label><label class="full">Deine Bestellung / Nachricht <span>*</span><textarea required name="message" minlength="10" maxlength="3000" rows="5" placeholder="Was dürfen wir für dich zubereiten? Bitte auch Sonderwünsche angeben."></textarea><span class="field-counter"><span data-message-count>0</span> / 3000</span></label></div><p class="form-privacy">Deine Angaben werden zur Bearbeitung über unseren Formulardienst Formspree übermittelt. Mehr dazu in den <a href="@/html/datenschutz.html">Datenschutzhinweisen</a>.</p><div class="form-footer"><span>* Pflichtfelder</span><button class="button button--primary" type="submit"><span>Vorbestellung anfragen</span>{arrow()}</button></div><p class="form-feedback" id="form-feedback" role="status" aria-live="polite" tabindex="-1"></p><p class="form-binding-note"><strong>Bitte beachten:</strong> Mindestens 1 Tag vorher bestellen und unsere persönliche Bestätigung abwarten.</p></form></section></section><section class="shell map-section" id="karte"><div class="map-placeholder" data-map-container><div class="map-pattern" aria-hidden="true"></div><div class="map-content"><p class="eyebrow">WIR SIND GLEICH HIER.</p><h2>Dinkelsbühl.<br><em>Dr.-Martin-Luther-Straße 18.</em></h2><p>Die interaktive Karte wird erst nach deinem Klick geladen.<br>Dabei wird eine Verbindung zu Google Maps hergestellt.</p><div><button class="button button--primary" type="button" data-load-map>Karte laden {arrow()}</button><a class="under-link" href="{MAP}" target="_blank" rel="noopener">Route extern öffnen ↗</a></div></div></div></section>'''
write('html/kontakt.html',page('Kontakt & Vorbestellung in Dinkelsbühl','Besuche Ersan’s Kebap in der Dr.-Martin-Luther-Straße 18, Dinkelsbühl. Öffnungszeiten, Telefon und Formular für Vorbestellungen.',contact,'contact'))
